-- Phase 3 Vcare data migration. Reviewed and approved by the client
-- 24 Sep 2026 after the numbers were printed and a rolled-back trial run.
-- Generated by scratch/vcare-phase3-plan.mjs from the dev database and the
-- client's source MongoDB; see 09-documentation/04-roadmap/PHASE-3-RUNBOOK.md.
--
-- Steps: 1 classify (871 goods, 36 services), 2 blank barcodes to NULL,
-- 3 warranty (306), 4 serial tracking (321), 5 receipts (2,578), 6 units
-- (from receipts and challan barcodes), 7 ledger: challan and receipt
-- movements replayed as migration_backfill, plus an opening balance per
-- product as migration_opening.
--
-- THE OPENING BALANCES WERE NOT COUNTED. They are worked backwards from the
-- old system's closing figures. A physical count is the only way to make
-- stock on hand true.
--
-- No ids are hard-coded: the store resolves by organisation name, products by
-- productCode, suppliers by company name, receipts by legacyRef. Every
-- statement is guarded, so a re-run changes nothing - proven by applying it
-- twice inside a transaction before shipping.


-- STEP 1. Classify. Everything marked service becomes goods, except names
-- matching the charge rule, which stay services and untracked. 871 rows on
-- the database this was generated from; 36 held back for review.
UPDATE "Product" p SET kind = 'goods', "trackingMode" = 'quantity', "updatedAt" = now()
 WHERE p."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND p.kind = 'service'
   AND (p."productName" !~* 'install|service|charge|labour|cabling|amc|annual|freight|visit' OR p."productCode" IN ('PRD202500041', 'PRD202500156', 'PRD202500306'));

-- STEP 2. A column that stores two kinds of nothing lies to every count.
UPDATE "InstallationChallanItem" i SET barcode = NULL
  FROM "InstallationChallan" c
 WHERE c.id = i."challanId" AND c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND btrim(i.barcode) = '';

-- STEP 3. Warranty months, as the client's old product master had them.
-- Only where Atlas has none, so a correction made since is never overwritten.
