  ) AS v(grn, key, supplier, at)
  JOIN LATERAL (SELECT x.id, x."storeId" FROM "Party" x
                 WHERE x."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND x."isSupplier"
                   AND upper(regexp_replace(btrim(COALESCE(NULLIF(x."companyName", ''), x."firstName")), '\s+', ' ', 'g')) = v.key
                 ORDER BY x."createdAt" LIMIT 1) p ON true
 WHERE NOT EXISTS (SELECT 1 FROM "GoodsReceiptNote" g WHERE g."storeId" = p."storeId" AND g."legacyRef" = v.grn);

INSERT INTO "GoodsReceiptNoteItem" (id, "storeId", "grnId", "srNo", "productId", "productName", "productCode", qty, "unitCostPaise", "taxRatePct", "warrantyMonths", "isRefurbished")
