  JOIN "GoodsReceiptNote" g ON g."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND g."legacyRef" = v.grn
  JOIN "Product" pr ON pr."storeId" = g."storeId" AND pr."productCode" = v.code
 WHERE NOT EXISTS (SELECT 1 FROM "GoodsReceiptNoteItem" i WHERE i."grnId" = g.id AND i."srNo" = v.sr);

