  ) AS v(grn, sr, code, serial, status, cond, cost, at)
  JOIN "Product" pr ON pr."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND pr."productCode" = v.code AND pr."trackingMode" = 'serial'
  LEFT JOIN "GoodsReceiptNote" g ON g."storeId" = pr."storeId" AND g."legacyRef" = v.grn
  LEFT JOIN "GoodsReceiptNoteItem" gi ON gi."grnId" = g.id AND gi."srNo" = v.sr
 WHERE NOT EXISTS (SELECT 1 FROM "StockUnit" u WHERE u."storeId" = pr."storeId"
                     AND u."productId" = pr.id AND upper(u."serialNo") = upper(v.serial));

-- STEP 6b. One unit per real barcode that left on an installation challan,
-- for serial-tracked products only. With the customer it was installed for;
-- its arrival is unknown, so receivedAt is the dispatch date and it says so.
INSERT INTO "StockUnit" (id, "storeId", "productId", "serialNo", status, condition, "partyId",
                         "receivedAt", "legacyRef", note, "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, x."storeId", x."productId", x.serial, 'with_customer', 'new', x."partyId",
       x."dispatchedAt", x.ref, 'Migrated from an installation challan. Arrival not recorded in the old system.', now(), now()
  FROM (SELECT DISTINCT ON (i."productId", upper(btrim(i.barcode)))
               c."storeId", i."productId", btrim(i.barcode) AS serial, so."partyId", c."dispatchedAt",
               COALESCE(c."legacyRef", c."challanNo") AS ref
          FROM "InstallationChallanItem" i
          JOIN "InstallationChallan" c ON c.id = i."challanId"
          JOIN "Product" p ON p.id = i."productId" AND p."trackingMode" = 'serial'
          LEFT JOIN "SalesOrder" so ON so.id = c."salesOrderId"
         WHERE c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c.status <> 'rejected' AND btrim(COALESCE(i.barcode, '')) <> ''
         ORDER BY i."productId", upper(btrim(i.barcode)), c."dispatchedAt" DESC) x
 WHERE NOT EXISTS (SELECT 1 FROM "StockUnit" u WHERE u."storeId" = x."storeId"
                     AND u."productId" = x."productId" AND upper(u."serialNo") = upper(x.serial));

UPDATE "InstallationChallanItem" i SET "stockUnitId" = u.id
  FROM "InstallationChallan" c, "StockUnit" u
 WHERE c.id = i."challanId" AND c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND i."stockUnitId" IS NULL
   AND u."storeId" = c."storeId" AND u."productId" = i."productId"
   AND upper(u."serialNo") = upper(btrim(i.barcode));

-- A unit from the old inventory that left on an installation challan is with
-- that customer, whatever its old status said. The challan names who.
UPDATE "StockUnit" u SET status = 'with_customer', "partyId" = COALESCE(x."partyId", u."partyId"), "updatedAt" = now()
  FROM (SELECT DISTINCT ON (i."stockUnitId") i."stockUnitId", so."partyId"
          FROM "InstallationChallanItem" i JOIN "InstallationChallan" c ON c.id = i."challanId"
          LEFT JOIN "SalesOrder" so ON so.id = c."salesOrderId"
         WHERE c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c.status <> 'rejected' AND i."stockUnitId" IS NOT NULL
         ORDER BY i."stockUnitId", c."dispatchedAt" DESC) x
 WHERE u.id = x."stockUnitId" AND u.note LIKE 'Migrated%'
   AND (u.status <> 'with_customer' OR (u."partyId" IS NULL AND x."partyId" IS NOT NULL));

INSERT INTO "StockUnitEvent" (id, "storeId", "unitId", "eventType", "toStatus", "toCondition", "partyId", "refType", "refNo", note, "createdAt")
SELECT gen_random_uuid()::text, u."storeId", u.id, 'migrated', u.status, u.condition, u."partyId",
       CASE WHEN u.note LIKE '%installation challan%' THEN 'InstallationChallan' ELSE 'GoodsReceiptNote' END,
       u."legacyRef", 'Brought over from the old system', u."receivedAt"
  FROM "StockUnit" u
 WHERE u."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND u.note LIKE 'Migrated%'
   AND NOT EXISTS (SELECT 1 FROM "StockUnitEvent" e WHERE e."unitId" = u.id AND e."eventType" = 'migrated');

-- STEP 7. The ledger, made complete. Challan outflows replayed as
-- migration_backfill; one opening balance per product as migration_opening.
--
-- THE OPENING BALANCE WAS NOT COUNTED. It is worked backwards from the old
-- system's closing figure so that the replay lands on it. Both reasons are
-- permanent, so a reconstructed movement is never mistaken for a real one.
-- A physical count is the only way to make stock on hand true.
--
-- balanceAfter on these rows is the running total of the replay itself.
-- Guarded: runs once per store, and never over a challan that already moved stock.
INSERT INTO "StockMovement" (id, "storeId", "productId", qty, reason, "refType", "refId", "refNo", "balanceAfter", note, "createdAt")
WITH 
    tracked AS (SELECT p.id, p."productCode" FROM "Product" p WHERE p."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND (p."trackingMode" <> 'none')),
    flows AS (
      SELECT rc."productId" AS pid, -rc.qty AS qty, rc."dispatchedAt" AS at,
             'RepairChallan'::text AS rt, rc.id AS rid, rc."challanNo" AS rno,
             'Replayed from a repair challan in the old system'::text AS note
        FROM "RepairChallan" rc JOIN tracked t ON t.id = rc."productId"
       WHERE rc."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND rc.status <> 'rejected' AND rc.qty > 0
         AND NOT EXISTS (SELECT 1 FROM "StockMovement" m WHERE m."refId" = rc.id)
      UNION ALL
      SELECT i."productId", -i.qty, c."dispatchedAt", 'InstallationChallan', c.id, c."challanNo",
             'Replayed from an installation challan in the old system'
        FROM "InstallationChallanItem" i JOIN "InstallationChallan" c ON c.id = i."challanId"
        JOIN tracked t ON t.id = i."productId"
       WHERE c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c.status <> 'rejected' AND i.qty > 0
         AND NOT EXISTS (SELECT 1 FROM "StockMovement" m WHERE m."refId" = c.id AND m."productId" = i."productId")
      UNION ALL
      SELECT gi."productId", gi.qty, g."receivedDate", 'GoodsReceiptNote', g.id, g."grnNo",
             'Replayed from a receipt in the old system'
        FROM "GoodsReceiptNoteItem" gi JOIN "GoodsReceiptNote" g ON g.id = gi."grnId"
        JOIN tracked t ON t.id = gi."productId"
       WHERE g."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND g."legacyRef" IS NOT NULL AND g.status = 'posted'
         AND NOT EXISTS (SELECT 1 FROM "StockMovement" m WHERE m."refId" = g.id)
    ),
    fsum AS (SELECT pid, sum(qty)::int AS total, sum(-qty) FILTER (WHERE qty < 0)::int AS outflow,
                    min(at) AS first_at, max(at) FILTER (WHERE qty < 0) AS last_out
               FROM flows GROUP BY pid),
    bal AS (SELECT b."productId" AS pid, sum(b."currentQty")::int AS qty
              FROM "ProductBalance" b JOIN tracked t ON t.id = b."productId" GROUP BY 1),
    src(code, qty) AS (VALUES ('PRD202500004', 4), ('PRD202600325', 2), ('PRD202600234', 12), ('PRD202600208', 9), ('PRD202600053', 16), ('PRD202600235', 36), ('PRD202600025', 33), ('PRD202600326', 5), ('PRD202600329', 1), ('PRD202600211', 6), ('PRD202600240', 62), ('PRD202600330', 1), ('PRD202600331', 1), ('PRD202600085', 1), ('PRD202600332', 0), ('PRD202600242', 0), ('PRD202600030', 4), ('PRD202600243', 1), ('PRD202600244', 14), ('PRD202600104', 0), ('PRD202600032', 7), ('PRD202600334', 1), ('PRD202600245', 4), ('PRD202600148', 2), ('PRD202600093', 5), ('PRD202600035', 1), ('PRD202600107', 10), ('PRD202600110', 1), ('PRD202600315', 1), ('PRD202600289', 0), ('PRD202600339', 1), ('PRD202600220', 1), ('PRD202600340', 26), ('PRD202600040', 18), ('PRD202600041', 54), ('PRD202600344', 772), ('PRD202600043', 20), ('PRD202600112', 4), ('PRD202600250', 2), ('PRD202600045', 1), ('PRD202600347', 0), ('PRD202600113', 1), ('PRD202600114', 2), ('PRD202600115', 10), ('PRD202600348', 7), ('PRD202600251', 42), ('PRD202600324', 2), ('PRD202600252', 1), ('PRD202500013', 60), ('PRD202500020', 3), ('PRD202500025', 2), ('PRD202500053', 253), ('PRD202600352', 13), ('PRD202600001', 22), ('PRD202600353', 95), ('PRD202600186', 0), ('PRD202600187', 0), ('PRD202600256', 10), ('PRD202600118', 0), ('PRD202600165', 1), ('PRD202600188', 4), ('PRD202600189', 0), ('PRD202600003', 12), ('PRD202600167', 3), ('PRD202600358', 0), ('PRD202600006', 8), ('PRD202600121', 0), ('PRD202600259', 428), ('PRD202600008', 9), ('PRD202600192', 7), ('PRD202600122', 3), ('PRD202600193', 1), ('PRD202600194', 10), ('PRD202600125', 2), ('PRD202600196', 2), ('PRD202600261', 9), ('PRD202600130', 1), ('PRD202600264', 1), ('PRD202600013', 190), ('PRD202600014', 18), ('PRD202600015', 51), ('PRD202600067', -1), ('PRD202600133', 8), ('PRD202600265', 11), ('PRD202600178', 14), ('PRD202600135', 1), ('PRD202600071', 28), ('PRD202600223', 19), ('PRD202600136', 0), ('PRD202600268', 0), ('PRD202600199', 10), ('PRD202600020', 2), ('