    plan AS (
      SELECT t.id AS pid, t."productCode" AS code,
             bal.qty AS balance,
             CASE WHEN bal.pid IS NULL THEN COALESCE(src.qty, 0) ELSE bal.qty END AS target,
             COALESCE(fsum.total, 0) AS flow_total,
             COALESCE(fsum.outflow, 0) AS outflow,
             -- The plug: what the opening must have been for the replay to land
             -- on the target. Products with a balance already carry it on the
             -- ledger, so their plug only has to cover the replayed flows.
             CASE WHEN bal.pid IS NULL THEN COALESCE(src.qty, 0) ELSE 0 END - COALESCE(fsum.total, 0) AS plug,
