             'Opening balance CALCULATED BACKWARDS from the old system''s closing figure - not counted.'::text AS note, 0 AS ord
        FROM plan WHERE plug <> 0
      UNION ALL
      SELECT pid, qty, at, 'migration_backfill', rt, rid, rno, note, 1 FROM flows
    )
SELECT gen_random_uuid()::text, (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1), pid, qty, reason, rt, rid, rno,
       (sum(qty) OVER (PARTITION BY pid ORDER BY at, ord, rid ROWS UNBOUNDED PRECEDING))::int, note, at
  FROM rows_
 WHERE NOT EXISTS (SELECT 1 FROM "StockMovement" m WHERE m."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1)
                     AND m.reason IN ('migration_opening', 'migration_backfill'));

-- The projection. Products that had no balance get one equal to their ledger;
-- every replayed product gets its real last-dispatch date, or the dead-stock
-- view would call every one of them dead.
INSERT INTO "ProductBalance" (id, "productId", "currentQty", "lastMovementAt", "updatedAt")
SELECT gen_random_uuid()::text, m."productId", sum(m.qty)::int, max(m."createdAt"), now()
  FROM "StockMovement" m
 WHERE m."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND m.reason IN ('migration_opening', 'migration_backfill')
   AND NOT EXISTS (SELECT 1 FROM "ProductBalance" b WHERE b."productId" = m."productId")
 GROUP BY m."productId";

UPDATE "ProductBalance" b SET "lastSoldAt" = GREATEST(b."lastSoldAt", x.last_out), "updatedAt" = now()
  FROM (SELECT m."productId", max(m."createdAt") AS last_out FROM "StockMovement" m
         WHERE m."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND m.reason = 'migration_backfill' AND m.qty < 0 GROUP BY 1) x
 WHERE b."productId" = x."productId" AND (b."lastSoldAt" IS NULL OR b."lastSoldAt" < x.last_out);
